import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
/**
 * 头像、名称、@用户名和“头衔”——Discourse 各列表（“关于”页面的
 * 团队、目录、组成员）中的用户区块。
 *
 * Flarum 没有用户头衔；该位置显示第一个用户组的名称，这也是
 * Discourse 在头衔来自用户组时的显示方式。
 */
export default class UserTile extends Component {
  view() {
    const {
      user,
      meta,
      size = 'normal'
    } = this.attrs;
    const displayName = user.displayName();
    const username = user.username();
    const group = (user.groups() || []).find(g => !!g);
    const url = app.route.user(user);
    return m("div", {
      className: `LcoyUserTile LcoyUserTile--${size}`
    }, m(Link, {
      href: url,
      className: "LcoyUserTile-avatar",
      tabindex: "-1",
      "aria-hidden": "true"
    }, m(Avatar, {
      user: user
    })), m("div", {
      className: "LcoyUserTile-info"
    }, m(Link, {
      href: url,
      className: "LcoyUserTile-name"
    }, m("span", {
      className: "LcoyUserTile-username"
    }, username), displayName !== username && m("span", {
      className: "LcoyUserTile-displayName"
    }, displayName)), group && m("span", {
      className: "LcoyUserTile-title"
    }, group.nameSingular()), meta && m("span", {
      className: "LcoyUserTile-meta"
    }, meta)));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/UserTile', UserTile);