/*
 * 社区页面各端点的访问（/api/lcoy-about、
 * /api/lcoy-directory、/api/lcoy-groups/:id/activity）。
 *
 * 它们不是 JSON:API 资源——“关于”页面把数据、文本和
 * 团队合并为一个响应——但用户以资源格式（`type: users`）
 * 返回并进入 store。这样 Avatar、`username()` 以及核心的
 * 个人资料路由对它们就如同对任何其他用户一样有效。
 */
import app from 'flarum/forum/app';
export const PERIODS = ['all', 'yearly', 'quarterly', 'monthly', 'weekly', 'daily'];
function apiUrl(path) {
  return `${(app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '')}${path}`;
}

/** 将随附返回的用户放入 store，并按 id 返回模型。 */
export function pushUsers(resources) {
  const users = {};
  resources.forEach(resource => {
    const user = app.store.pushObject(resource);
    if (user) users[resource.id] = user;
  });
  return users;
}
export function fetchAbout() {
  return app.request({
    method: 'GET',
    url: apiUrl('/lcoy-about')
  });
}
export function fetchDirectory(params) {
  // 空参数不参与拼接：API URL 与由已保存链接生成的 URL 一致，
  // 由服务端应用默认值。
  const query = Object.fromEntries(Object.entries(params).filter(([, value]) => value !== undefined && value !== '' && value !== null));
  return app.request({
    method: 'GET',
    url: apiUrl('/lcoy-directory'),
    params: query
  });
}
export function fetchGroupActivity(groupId, page) {
  return app.request({
    method: 'GET',
    url: apiUrl(`/lcoy-groups/${groupId}/activity`),
    params: {
      page
    }
  });
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/api', { PERIODS: PERIODS,pushUsers: pushUsers,fetchAbout: fetchAbout,fetchDirectory: fetchDirectory,fetchGroupActivity: fetchGroupActivity, });